def nonzero_bbox(g,bg):
    cells=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v not in (bg,0)]
    rs=[i for i,_ in cells]; cs=[j for _,j in cells]
    return min(rs),min(cs),max(rs),max(cs)

def transform(g):
    bg=g[0][0]
    r0,c0,r1,c1=nonzero_bbox(g,bg)
    pat=crop(g,r0,c0,r1-r0+1,c1-c0+1)
    ti,tj=find_block(g,0)
    return paste(g,hflip(pat),ti,tj)

